"""Deterministic ingestion and supplier context from analysis-team evidence JSON.

The reader intentionally knows very little about evidence semantics.  It standardizes the
current analysis export, preserves unfamiliar fields, and limits quote-derived conclusions to
quote history.  In particular, a historical quote is not evidence of supplier pressure or
preferences.
"""

from __future__ import annotations

import json
import math
import re
from collections.abc import Mapping
from pathlib import Path
from typing import Any


class EvidenceInputError(ValueError):
    """Raised when an evidence document cannot be read as the expected JSON array."""


_NUMBER = re.compile(r"^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$")
_WRAPPER_KEYS = {"Information", "Source", "Priority (Argument wise)"}
_PROFILE_DIMENSIONS = (
    "cash_sensitive",
    "capacity_sensitive",
    "price_rigid",
    "quality_sensitive",
)
_CANONICAL_FIELD_ALIASES = {
    "supplier_id": {"supplier_id", "supplier id", "supplier", "supplier number"},
    "part_id": {"part_id", "part id", "part", "part number", "item", "item number"},
    "unit_price": {"unit_price", "unit price", "price", "preis"},
    "quote_date": {"quote_date", "quote date", "date", "offer date"},
    "currency": {"currency", "currency code", "währung", "waehrung"},
    "payment_days": {"payment_days", "payment days", "payment terms", "zahlungsziel"},
    "lead_time_days": {"lead_time_days", "lead time", "lead time days", "delivery days"},
    "incoterm": {"incoterm", "incoterms"},
}


def load_evidence(source: str | Path | list[object]) -> list[dict[str, Any]]:
    """Load, validate, and normalize an analysis-team evidence array.

    ``source`` can be a path to JSON or an already-loaded list.  Records need only be objects:
    missing or unfamiliar ``Information`` fields remain usable so future evidence types can be
    passed through without changes to this reader.
    """
    if isinstance(source, (str, Path)):
        path = Path(source)
        try:
            raw = json.loads(path.read_text(encoding="utf-8"))
        except OSError as exc:
            raise EvidenceInputError(f"could not read evidence JSON at {path}: {exc}") from exc
        except json.JSONDecodeError as exc:
            raise EvidenceInputError(f"invalid evidence JSON at {path}: {exc.msg}") from exc
    elif isinstance(source, list):
        raw = source
    else:
        raise EvidenceInputError("evidence input must be a JSON path or an already-loaded list")

    if not isinstance(raw, list):
        raise EvidenceInputError("evidence JSON must contain a top-level array")

    normalized: list[dict[str, Any]] = []
    for index, record in enumerate(raw):
        if not isinstance(record, Mapping):
            raise EvidenceInputError(f"evidence record at index {index} must be an object")
        normalized.append(_normalize_record(record))
    return normalized


def filter_evidence(
    evidence: list[Mapping[str, Any]], supplier_id: str, part_id: str | None = None
) -> list[dict[str, Any]]:
    """Return normalized records for ``supplier_id`` and, optionally, ``part_id``.

    The return value is a copy of matching records, so callers may safely add presentation data
    without changing the loaded evidence.
    """
    return [
        dict(record)
        for record in evidence
        if record.get("supplier_id") == supplier_id and (part_id is None or record.get("part_id") == part_id)
    ]


def bind_evidence_scope(
    evidence: list[Mapping[str, Any]], supplier_id: str, part_id: str | None = None
) -> list[dict[str, Any]]:
    """Bind unscopeable supplier-upload records to the live negotiation identity.

    A supplier attachment often has commercial rows but no arena supplier or part ID.  The
    caller already knows that identity from the live supplier thread, so this function attaches
    it explicitly rather than trying to infer it from CSV content.  Existing non-empty IDs must
    agree with the supplied scope; disagreement raises :class:`EvidenceInputError` to prevent
    evidence from one supplier being silently used for another.
    """
    if not isinstance(supplier_id, str) or not supplier_id:
        raise EvidenceInputError("supplier_id must be a non-empty string when binding evidence scope")
    if part_id is not None and (not isinstance(part_id, str) or not part_id):
        raise EvidenceInputError("part_id must be a non-empty string or None when binding evidence scope")

    bound: list[dict[str, Any]] = []
    for index, record in enumerate(evidence):
        if not isinstance(record, Mapping):
            raise EvidenceInputError(f"evidence record at index {index} must be an object")
        existing_supplier = record.get("supplier_id")
        existing_part = record.get("part_id")
        if existing_supplier not in (None, supplier_id):
            raise EvidenceInputError(
                f"evidence record at index {index} belongs to {existing_supplier!r}, not {supplier_id!r}"
            )
        if part_id is not None and existing_part not in (None, part_id):
            raise EvidenceInputError(
                f"evidence record at index {index} belongs to part {existing_part!r}, not {part_id!r}"
            )
        copy = dict(record)
        copy["supplier_id"] = supplier_id
        if part_id is not None:
            copy["part_id"] = part_id
        bound.append(copy)
    return bound


def build_supplier_context(
    evidence: list[Mapping[str, Any]], supplier_id: str, part_id: str | None = None
) -> dict[str, Any]:
    """Build a JSON-serializable, traceable context for one supplier and optional part.

    Only records whose normalized ``kind`` is ``quote`` contribute to ``quote_history``.  The
    profile deliberately remains unknown until a future evidence-specific rule is added.
    """
    matches = filter_evidence(evidence, supplier_id, part_id)
    quotes = [record for record in matches if record.get("kind") == "quote"]

    return {
        "supplier_id": supplier_id,
        "part_id": part_id,
        "evidence": [_context_evidence(record) for record in matches],
        "quote_history": _quote_history(quotes),
        "supplier_profile": {dimension: {"state": "unknown", "confidence": 0.0} for dimension in _PROFILE_DIMENSIONS},
        "evidence_gaps": _evidence_gaps(matches),
    }


def _normalize_record(record: Mapping[str, Any]) -> dict[str, Any]:
    information_value = record.get("Information", {})
    information = _normalize_value(information_value) if isinstance(information_value, Mapping) else {}
    if isinstance(information, Mapping):
        information = _canonicalize_information(information)
    wrapper_fields = {key: _normalize_value(value) for key, value in record.items() if key not in _WRAPPER_KEYS}
    if "Information" in record and not isinstance(information_value, Mapping):
        # A malformed or future non-object payload is retained rather than preventing unrelated
        # evidence from being ingested. It simply cannot supply the standard identity fields.
        wrapper_fields["Information"] = _normalize_value(information_value)
    # CSV extracts retain an exact line-range source but normally have no separate ID.  The
    # source is therefore the stable evidence ID for those records, preserving traceability.
    record_id = information.get("id") or wrapper_fields.get("id") or record.get("Source")
    return {
        "id": record_id,
        "kind": _evidence_kind(information, wrapper_fields, record_id),
        "supplier_id": information.get("supplier_id") or wrapper_fields.get("supplier_id"),
        "part_id": information.get("part_id") or wrapper_fields.get("part_id"),
        "source": _normalize_value(record.get("Source")),
        "priority": _normalize_value(record.get("Priority (Argument wise)")),
        "data": information,
        "record_fields": wrapper_fields,
    }


def _normalize_value(value: Any) -> Any:
    """Recursively convert safe scalar encodings while retaining all values and keys."""
    if isinstance(value, Mapping):
        return {str(key): _normalize_value(item) for key, item in value.items()}
    if isinstance(value, list):
        return [_normalize_value(item) for item in value]
    if isinstance(value, str):
        stripped = value.strip()
        lower = stripped.lower()
        if lower == "true":
            return True
        if lower == "false":
            return False
        if _NUMBER.fullmatch(stripped):
            number = float(stripped) if any(marker in stripped.lower() for marker in (".", "e")) else int(stripped)
            if math.isfinite(float(number)):
                return number
    return value


def _evidence_kind(information: Mapping[str, Any], wrapper_fields: Mapping[str, Any], record_id: Any) -> str:
    for field in ("kind", "evidence_kind", "type"):
        value = information.get(field, wrapper_fields.get(field))
        if isinstance(value, str) and value:
            return value
    if isinstance(record_id, str) and ":" in record_id:
        prefix = record_id.split(":", 1)[0]
        if prefix in {"quote", "document", "payment", "financial", "capacity", "quality"}:
            return prefix
    # An extracted supplier row with a recognizable price field is commercial quote evidence,
    # not a basis for inferring supplier pressure or preferences.
    if "unit_price" in information:
        return "quote"
    return "unknown"


def _canonicalize_information(information: Mapping[str, Any]) -> dict[str, Any]:
    """Retain supplied CSV headers and expose a small set of deterministic aliases."""
    result = dict(information)
    normalized_keys = {
        _header_key(str(key)): key
        for key in information
    }
    for canonical, aliases in _CANONICAL_FIELD_ALIASES.items():
        if canonical in result:
            continue
        for alias in aliases:
            original_key = normalized_keys.get(_header_key(alias))
            if original_key is not None:
                result[canonical] = information[original_key]
                break
    return result


def _header_key(value: str) -> str:
    return " ".join(value.strip().lower().replace("_", " ").replace("-", " ").split())


def _context_evidence(record: Mapping[str, Any]) -> dict[str, Any]:
    """Present one normalized record without dropping unfamiliar analysis output."""
    result = {
        "id": record.get("id"),
        "kind": reco…5749 tokens truncated…case in the final: (\S+)")
# Practice: the case list shows every practice case file; only those marked hosted can be played
# (a session on another is a 403). Without the marker every listed case counts as hosted.
HOSTED_FIELD = "hosted"


class RemoteTable:
    """The arena over HTTP: the practice arena, the final, or a hosted sandbox."""

    def __init__(self, client, case=None):
        self.client, self.session_id, self.case, self.done = client, None, case, None

    def open(self, case_id):
        try:
            r = self.client.open_session(case_id)
        except ArenaError as e:
            running = RUNNING.search(str(e.detail)) if e.status == 409 else None
            if not (running and self.case):
                raise
            return self.resume(running.group(1))
        self.session_id = r["session_id"]
        log.info("session %s", self.session_id)
        return r["case"], r["threads"]

    def resume(self, session_id):
        """Pick up a final session this team already started (e.g. after a crash): every thread
        so far, from the arena."""
        self.session_id = session_id
        log.info("resuming session %s", session_id)
        state = self.client.session(session_id)
        if state["status"] == "ended":
            self.done = self.result()
        return self.case, {s: self.client.thread(session_id, s)["messages"] for s in state["threads"]}

    def send(self, supplier_id, message):
        return self.client.send_message(self.session_id, supplier_id, message)

    def close(self, supplier_id, message):
        reply = self.client.send_message(self.session_id, supplier_id, message)
        return reply.get("result", reply)  # the supplier's last e-mail carries the result

    def attachment(self, attachment_id):
        return self.client.attachment(self.session_id, attachment_id)

    def missed(self, supplier_id, error):
        """After a 409: the result if the case has ended (e.g. at a wave's cap), else what the
        thread now says (a timeout answer, or the reason it ended)."""
        state = self.client.session(self.session_id)
        if state.get("status") == "ended":
            return {"result": state.get("result") or {"deal": False, "end_reason": state.get("end_reason")}}
        t = self.client.thread(self.session_id, supplier_id)
        last = (t.get("timeouts") or [{}])[-1]
        sheet = [{"term_sheet_id": t["offer_id"], "terms": last.get("terms", {})}]
        return {
            "from": "arena",
            "status": "walked_away" if t["closed"] else t["status"],
            "term_sheets": [] if t["closed"] else sheet,
            "body": f"({error.detail})",
            "missing_fields": last.get("missing_fields", []),
            "attachments": [],
        }

    def result(self):
        state = self.client.session(self.session_id)
        return state.get("result") or {"deal": False, "end_reason": state.get("end_reason"), **state}


def latest(events):
    """The supplier's latest message in a thread."""
    return next(m for m in reversed(events) if m.get("from") != "buyer")


def standing(events):
    """(term_sheet_id, terms) of the supplier's standing term sheet, or (None, {})."""
    sheets = latest(events).get("term_sheets") or []
    return (sheets[0]["term_sheet_id"], sheets[0]["terms"]) if sheets else (None, {})


def live_threads(threads):
    """Suppliers whose thread has not ended."""
    return [sid for sid, ev in threads.items() if latest(ev).get("status") not in ENDED]


def moves_left(case, events):
    """Messages you may still send in this thread (the round limit counts each of them)."""
    return case.get("round_limit", 10) - sum(m.get("from") == "buyer" for m in events)


def fetch_documents(table, message):
    """Download every attachment of a supplier message and add its text."""
    for att in message.get("attachments") or []:
        if att.get("attachment_id") and "text" not in att:
            att["text"] = read_document(att["name"], table.attachment(att["attachment_id"]))
    return message


def closing_move(case, threads):
    """Accept the cheapest standing term sheet that keeps the must-haves and beats the alternative
    (C with each supplier's standard terms), else walk away - what to do when time runs out."""
    alt = case["buyer"].get("alternative") or {}
    c_alt = total_cost(case, alt["terms"]) if alt.get("terms", {}).get("unit_price") else float("inf")
    best = None
    for sid in live_threads(threads):
        sheet_id, terms = standing(threads[sid])
        std = standard_terms(threads[sid])
        if sheet_id and must_haves_ok(case, terms, std) and (c := total_cost(case, terms, std)) < c_alt:
            best = min(best or (c, sid, sheet_id), (c, sid, sheet_id))
    if best is None:
        return {"supplier_id": live_threads(threads)[0], "message": {"action": {"type": "walk_away"}}}
    return {"supplier_id": best[1], "message": {"action": {"type": "accept", "term_sheet_id": best[2]}}}


def play(table, case_id, agent, deadline=None):
    """Play one case to its end. `deadline` (time.time(), or a function returning it): a Live Final
    wave's cap - shortly before it, `closing_move` closes the case so it does not end without a deal."""
    case, threads = table.open(case_id)
    if getattr(table, "done", None):  # resumed a case that had already ended
        return table.done
    for events in threads.values():
        for m in events:
            fetch_documents(table, m)
    slowest = 0.0  # the longest round so far: decision + the supplier's reply
    while live_threads(threads):
        t0 = time.monotonic()
        cap = deadline() if callable(deadline) else deadline
        if cap and time.time() > cap - max(CLOSE_BEFORE_CAP_S, slowest + ROUND_MARGIN_S):
            log.info("%s: the wave's cap is near - closing", case_id)
            close = getattr(agent, "close", None)
            decision = close(case, threads) if callable(close) else closing_move(case, threads)
        else:
            decision = agent.decide(case, threads)
        if (took := time.monotonic() - t0) > MOVE_LIMIT_S * 0.75:
            log.warning("decision took %.1fs - the limit is %ss per message", took, MOVE_LIMIT_S)
        sid, msg = decision["supplier_id"], decision["message"]
        try:
            if msg.get("action"):
                log.info("%s %s", sid, msg["action"])
                return table.close(sid, msg)
            reply = table.send(sid, msg)
        except ArenaError as e:
            if e.status != 409:
                raise
            log.info("%s: %s", sid, e.detail)
            reply = table.missed(sid, e)  # e.g. late, or the thread or the case has ended
            if msg.get("action") and "result" not in reply:  # the case goes on: decide again
                threads[sid].append(fetch_documents(table, reply))
                continue
        if "result" in reply:  # the reply ended the case, e.g. the last supplier walked away
            return reply["result"]
        threads[sid] += [{**msg, "from": "buyer"}, fetch_documents(table, reply)]
        slowest = max(slowest, time.monotonic() - t0)
        log.info("%s %s %s", sid, reply.get("status"), standing(threads[sid])[1])
    return table.result()


def hosted(cases):
    """The cases you can play: those marked hosted, or all of them if the list has no marker."""
    if any(HOSTED_FIELD in c for c in cases):
        return [c for c in cases if c.get(HOSTED_FIELD)]
    return cases


def quota_used_up(error):
    """The practice quota's 429 ("practice limit: …"): retrying does not help before it resets."""
    return isinstance(error, ArenaError) and error.status == 429 and str(error.detail).startswith("practice limit")


def play_all(new_table, case_ids, new_agent, parallel=8):
    """Play many cases at once (e.g. every practice case). `new_table()` and `new_agent()` give
    each case its own table and agent. Once the practice quota is used up, no further case starts.
    Returns {case_id: result or the exception that stopped it}."""
    used_up = threading.Event()

    def one(case_id):
        if used_up.is_set():
            return case_id, ArenaError(429, "not started: the practice quota is used up")
        try:
            return case_id, play(new_table(), case_id, new_agent())
        except ArenaError as e:
            if quota_used_up(e):
                used_up.set()
                log.warning("practice quota used up: %s", e.detail)
            elif e.status == 403:
                log.warning("%s: %s", case_id, e.detail)  # e.g. not hosted for practice
            else:
                log.exception("%s failed", case_id)
            return case_id, e
        except Exception as e:  # one broken case must not stop the others
            log.exception("%s failed", case_id)
            return case_id, e

    with ThreadPoolExecutor(max_workers=parallel) as pool:
        return dict(pool.map(one, case_ids))


def play_waves(client, new_agent, waves=5, parallel=10, poll=5.0):
    """The Live Final: wait for each wave, play its cases in parallel within the wave's cap, wait
    for the next. Keep it running from before the first wave until the last has closed; it returns
    after `waves` waves have closed and every case has finished: {case_id: result or exception}."""
    started, closed, caps = {}, set(), {}  # caps: wave -> its cap as time.time()

    def one(case, deadline):
        try:
            return play(RemoteTable(client, case), case["case_id"], new_agent(), deadline)
        except Exception as e:  # one broken case must not stop the others
            log.exception("%s failed", case["case_id"])
            return e

    with ThreadPoolExecutor(max_workers=parallel) as pool:
        while len(closed) < waves or not all(f.done() for f in started.values()):
            try:
                cases = client.cases("final")
            except ArenaError as e:
                if e.status != 403:  # 403: no wave has started yet
                    raise
                cases = []
            for case in cases:
                if not case.get("open"):
                    closed.add(case["wave"])
                    continue
                if case.get("seconds_left") is not None:  # each wave has its own cap; follow an extension
                    caps[case["wave"]] = time.time() + case["seconds_left"]
                if case["case_id"] not in started and case.get("seconds_left"):
                    if case["wave"] not in {c["wave"] for c in cases if c["case_id"] in started}:
                        log.warning("wave %s started: %s", case["wave"], case.get("theme"))
                    started[case["case_id"]] = pool.submit(one, case, functools.partial(caps.get, case["wave"]))
            time.sleep(poll)
    return {case_id: f.result() for case_id, f in started.items()}
