"""Normalize supplier quote PDFs, CSV rows, and offer messages into sourced context."""

from __future__ import annotations

import re
from collections.abc import Mapping
from typing import Any

from .intelligence import EvidenceInputError, contexts_from_records


_OFFER_ID = re.compile(r"\boffer:[\w.-]+\b", re.IGNORECASE)
_PART_ID = re.compile(r"\bpart:[\w.-]+\b", re.IGNORECASE)
_INDEX_COST_CLAIM = re.compile(
    r"\b(?P<series>[A-Z][A-Z0-9-]*)\s+rose\s+(?P<change>\d+(?:[.,]\d+)?)\s*%"
    r"\s+(?:in|over)\s+(?P<period>[^.]{1,60}?)\s+and\s+is\s+"
    r"(?P<share>\d+(?:[.,]\d+)?)\s*%\s+of\s+(?:our|the)\s+cost\b",
    re.IGNORECASE,
)


def quote_pdf_record(text: str, source: str, supplier_id: str | None = None) -> dict[str, Any]:
    """Convert a supplier quote PDF's structured sections to one provenance record."""
    from arena_kit.docs import quote_terms

    sections = quote_terms(text)
    offer_match = _OFFER_ID.search(text)
    part_match = _PART_ID.search(text)
    offer_id = offer_match.group(0) if offer_match else None
    part_id = part_match.group(0) if part_match else None

    # Retain each source section, while exposing one effective term map for negotiation.
    effective_terms: dict[str, Any] = {}
    for section in ("standard", "fixed", "stated", "agreed"):
        effective_terms.update(sections.get(section) or {})
    information: dict[str, Any] = {
        "kind": "quote" if effective_terms else "document",
        "supplier_id": supplier_id,
        "part_id": part_id,
        "offer_id": offer_id,
        "currency": "EUR" if "unit_price" in effective_terms else None,
        "term_sections": sections,
        "terms": effective_terms,
        **effective_terms,
    }
    if not effective_terms:
        information["document_text"] = text[:20000]
    return _record(information, source, priority=1 if effective_terms else 3)


def supplier_message_records(message: Mapping[str, Any], supplier_id: str) -> list[dict[str, Any]]:
    """Extract quote-sheet terms and explicit index/cost claims from one supplier email."""
    source = _message_source(message)
    records: list[dict[str, Any]] = []
    body = str(message.get("body") or "")
    claims: dict[tuple[str, str], dict[str, Any]] = {}

    for match in _INDEX_COST_CLAIM.finditer(body):
        series = match.group("series").upper()
        claims[(series, match.group("change"))] = {
            "kind": "claim",
            "claim_type": "index_change_and_cost_share",
            "series": series,
            "index_change_pct": _number(match.group("change")),
            "time_window": match.group("period").strip(),
            "cost_share_pct": _number(match.group("share")),
            "claim_text": match.group(0),
        }

    for claim in message.get("claims") or []:
        if not isinstance(claim, Mapping):
            continue
        claim_type = str(claim.get("type") or "supplier_claim")
        asserted = claim.get("asserted") if isinstance(claim.get("asserted"), Mapping) else {}
        refs = claim.get("refs") if isinstance(claim.get("refs"), list) else []
        series = next((_series_from_ref(ref) for ref in refs if _series_from_ref(ref)), None)
        change = asserted.get("change_pct")
        key = (series or claim_type, str(change) if change is not None else "")
        normalized = claims.setdefault(key, {
            "kind": "claim",
            "claim_type": claim_type,
            "series": series,
        })
        normalized["structured_claim"] = dict(claim)
        if refs:
            normalized["refs"] = refs
        if change is not None:
            normalized.setdefault("index_change_pct", _number(change))
        for field, value in asserted.items():
            normalized.setdefault(field, value)

    for index, information in enumerate(claims.values()):
        information = {key: value for key, value in information.items() if value is not None}
        information.update({"supplier_id": supplier_id, "claim_id": f"{source}:claim:{index}"})
        records.append(_record(information, source, priority=1))

    for sheet in message.get("term_sheets") or []:
        if not isinstance(sheet, Mapping):
            continue
        terms = sheet.get("terms") if isinstance(sheet.get("terms"), Mapping) else {}
        offer_id = sheet.get("term_sheet_id")
        if not offer_id and not terms:
            continue
        information = {
            "kind": "quote",
            "supplier_id": supplier_id,
            "offer_id": offer_id,
            "terms": dict(terms),
            **dict(terms),
        }
        if str(terms.get("currency") or "").strip():
            information["currency"] = terms["currency"]
        records.append(_record(information, source, priority=1))
    return records


def build_thread_supplier_context(
    events: list[Mapping[str, Any]], supplier_id: str, part_id: str | None = None
) -> dict[str, Any]:
    """Combine all supplier evidence in a thread, preserving the source of every fact."""
    records: list[dict[str, Any]] = []
    for event in events:
        if event.get("from") == "buyer":
            continue
        # Attachments come first so an attached quote PDF is the primary source for
        # that offer; the email term sheet fills any fields the PDF omitted.
        for attachment in event.get("attachments") or []:
            records.extend(_attachment_records(attachment, supplier_id))
        records.extend(supplier_message_records(event, supplier_id))

    records = _deduplicate(records)
    try:
        contexts = contexts_from_records(records, supplier_id, part_id)
    except EvidenceInputError as exc:
        return {
            "schema": "supplier_context_v1",
            "supplier_id": supplier_id,
            "contexts": [],
            "context_error": str(exc),
        }
    return {"schema": "supplier_context_v1", "supplier_id": supplier_id,
            "records": records, "contexts": contexts}


def context_for_part(bundle: Mapping[str, Any], part_id: str | None = None) -> dict[str, Any] | None:
    contexts = [item for item in bundle.get("contexts", []) if isinstance(item, dict)]
    if part_id is not None:
        matches = [item for item in contexts if item.get("part_id") == part_id]
        return matches[0] if len(matches) == 1 else None
    return contexts[0] if len(contexts) == 1 else None


def _attachment_records(attachment: Mapping[str, Any], supplier_id: str) -> list[dict[str, Any]]:
    records = attachment.get("csv_records")
    if isinstance(records, list):
        output = list(records)
    else:
        output = []
    name = str(attachment.get("name") or "supplier_document")
    source = f"{attachment.get('attachment_id') or name} ({name})"
    text = attachment.get("text")
    if name.lower().endswith(".pdf") and isinstance(text, str):
        output.append(quote_pdf_record(text, source, supplier_id))
    # Preserve a precomputed context from external callers when no raw rows are attached.
    if not output:
        bundle = attachment.get("supplier_context") or {}
        for context in bundle.get("contexts") or []:
            for item in context.get("evidence") or []:
                if not isinstance(item, Mapping):
                    continue
                information = dict(item.get("data") or {})
                information.update({"id": item.get("id"), "kind": item.get("kind", "unknown")})
                output.append(_record(information, str(item.get("source") or source), item.get("priority", 3)))
    return output


def _record(information: Mapping[str, Any], source: str, priority: int) -> dict[str, Any]:
    return {
        "Information": dict(information),
        "Source": source,
        "Priority (Argument wise)": priority,
    }


def _deduplicate(records: list[dict[str, Any]]) -> list[dict[str, Any]]:
    output = []
    positions: dict[tuple[str, str], int] = {}
    for record in records:
        information = record.get("Information") or {}
        kind = str(information.get("kind") or ("quote" if "unit_price" in information else "unknown"))
        identity = information.get("id") or information.get("offer_id") or information.get("claim_id")
        if identity is None:
            identity = record.get("Source")
        key = (kind, str(identity))
        if key not in positions:
            positions[key] = len(output)
            copy = dict(record)
            copy["Information"] = dict(information)
            copy["Information"]["source_refs"] = [record.get("Source")]
            output.append(copy)
            continue
        existing = output[positions[key]]
        existing_info = existing["Information"]
        for field, value in information.items():
            if field not in existing_info or existing_info[field] in (None, ""):
                existing_info[field] = value
        source_refs = existing_info.setdefault("source_refs", [])
        if record.get("Source") not in source_refs:
            source_refs.append(record.get("Source"))
    return output


def _message_source(message: Mapping[str, Any]) -> str:
    return str(message.get("message_id") or message.get("offer_id") or "supplier_message")


def _series_from_ref(ref: Any) -> str | None:
    if not isinstance(ref, str) or not ref.startswith("idx:"):
        return None
    return ref[4:].split("@", 1)[0]


def _number(value: Any) -> float | Any:
    try:
        return float(str(value).replace(",", "."))
    except (TypeError, ValueError):
        return value
"""Read the documents suppliers attach: PDF and XLSX to text, a quote PDF to structured terms."""

import io
import re

LABELS = {
    "Unit price (EUR)": "unit_price",
    "Payment terms (days net)": "payment_days",
    "Lead time (days)": "lead_time_days",
    "Volume per year (pcs)": "volume_per_year",
    "Contract term (months)": "contract_months",
    "Price valid from": "effective_date",
    "Index clause": "index_clause",
    "Incoterm": "incoterm",
    "Tooling (EUR)": "tooling_eur",
    "Quality commitment (ppm)": "ppm_commitment",
    "Chargeback per complaint (EUR)": "chargeback_eur_per_complaint",
}
SECTIONS = {
    "Offered terms": "stated",
    "Our standard terms": "standard",
    "Terms fixed by your enquiry": "fixed",
    "Agreed terms": "agreed",
}
CLAUSE = re.compile(r"(\S+), (\d+(?:[.,]\d+)?)% material, deadband ([\d.,]+) %, base (\S+)")


def read_document(name, data):
    """The text of an attachment: PDF pages, XLSX rows (formulas as written), or plain text."""
    if name.lower().endswith(".pdf"):
        from pypdf import PdfReader

        return "\n".join(p.extract_text() or "" for p in PdfReader(io.BytesIO(data)).pages)
    if name.lower().endswith(".xlsx"):
        from openpyxl import load_workbook

        wb = load_workbook(io.BytesIO(data))
        return "\n".join(
            f"[{ws.title}]\n"
            + "\n".join(" | ".join("" if v is None else str(v) for v in row) for row in ws.iter_rows(values_only=True))
            for ws in wb.worksheets
        )
    return data.decode("utf-8", "replace")


def _value(field, text):
    if field == "index_clause":
        m = CLAUSE.match(text)
        if not m:
            return None
        series, share, deadband, base = m.groups()
        return {
            "series": series,
            "material_share": float(share.replace(",", ".")) / 100,
            "deadband_pct": float(deadband.replace(",", ".")),
            "base_month": base,
        }
    if field in ("effective_date", "incoterm"):
        return text
    number = text.replace(" ", "").replace(",", ".")
    return float(number) if "eur" in field or field == "unit_price" else int(float(number))


def quote_terms(text):
    """Terms per section of a quote or order confirmation PDF: stated, standard, fixed, agreed."""
    out, section = {}, None
    for line in text.splitlines():
        line = line.strip()
        section = next((key for head, key in SECTIONS.items() if line.startswith(head)), section)
        label = next((lab for lab in LABELS if line.startswith(lab + " ")), None)
        if section and label:
            out.setdefault(section, {})[LABELS[label]] = _value(LABELS[label], line[len(label) :].strip())
    return out


def standard_terms(events):
    """The supplier's standard terms from the latest quote PDF in a thread (empty if none)."""
    for msg in reversed(events):
        for att in msg.get("attachments") or []:
            if att.get("name", "").startswith("quote") and att.get("text"):
                return quote_terms(att["text"]).get("standard", {})
    return {}
"""Play cases with an agent against the arena over HTTP - the hosted arena (practice, sandbox,
final) or `arena-sim`, the local contract simulator. Both speak the same API.

An agent is any object with `decide(case, threads) -> {"supplier_id": ..., "message": {...}}`:
  threads: {supplier_id: [message, ...]} - every e-mail so far, both directions, in order;
           supplier attachments carry readable `text`; CSVs also carry extracted `csv_records`.
           The supplier agent normalizes email claims and PDF/CSV evidence into one context.
  message: subject, body, up to 3 term sheets, refs - or an "action" that closes the case:
           {"type": "accept", "term_sheet_id": ...} or {"type": "walk_away"}.
"""

import functools
import io
import logging
import re
import threading
import time
from concurrent.futures import ThreadPoolExecutor

from .client import ArenaError
from .cost import must_haves_ok, total_cost
from .docs import read_document, standard_terms

log = logging.getLogger("arena")

ENDED = {"walked_away", "no_bid"}
# A message later than this after the supplier's last one counts as a timeout.
MOVE_LIMIT_S = 60
# In the Live Final, close this long before the wave's cap - or the slowest round of the case so far
# (your decision plus a supplier reply of up to about a minute) plus a margin, if that is longer.
CLOSE_BEFORE_CAP_S, ROUND_MARGIN_S = 90, 15
RUNNING = re.compile(r"one session per case in the final: (\S+)")
# Practice: the case list shows every practice case file; only those marked hosted can be played
# (a session on another is a 403). Without the marker every listed case counts as hosted.
HOSTED_FIELD = "hosted"


class RemoteTable:
    """The arena over HTTP: the practice arena, the final, or a hosted sandbox."""

    def __init__(self, client, case=None):
        self.client, self.session_id, self.case, self.done = client, None, case, None

    def open(self, case_id):
        try:
            r = self.client.open_session(case_id)
        except ArenaError as e:
            running = RUNNING.search(str(e.detail)) if e.status == 409 else None
            if not (running and self.case):
                raise
            return self.resume(running.group(1))
        self.session_id = r["session_id"]
        log.info("session %s", self.session_id)
        return r["case"], r["threads"]

    def resume(self, session_id):
        """Pick up a final session this team already started (e.g. after a crash): every thread
        so far, from the arena."""
        self.session_id = session_id
        log.info("resuming session %s", session_id)
        state = self.client.session(session_id)
        if state["status"] == "ended":
            self.done = self.result()
        return self.case, {s: self.client.thread(session_id, s)["messages"] for s in state["threads"]}

    def send(self, supplier_id, message):
        return self.client.send_message(self.session_id, supplier_id, message)

    def close(self, supplier_id, message):
        reply = self.client.send_message(self.session_id, supplier_id, message)
        return reply.get("result", reply)  # the supplier's last e-mail carries the result

    def attachment(self, attachment_id):
        return self.client.attachment(self.session_id, attachment_id)

    def missed(self, supplier_id, error):
        """After a 409: the result if the case has ended (e.g. at a wave's cap), else what the
        thread now says (a timeout answer, or the reason it ended)."""
        state = self.client.session(self.session_id)
        if state.get("status") == "ended":
            return {"result": state.get("result") or {"deal": False, "end_reason": state.get("end_reason")}}
        t = self.client.thread(self.session_id, supplier_id)
        last = (t.get("timeouts") or [{}])[-1]
        sheet = [{"term_sheet_id": t["offer_id"], "terms": last.get("terms", {})}]
        return {
            "from": "arena",
            "status": "walked_away" if t["closed"] else t["status"],
            "term_sheets": [] if t["closed"] else sheet,
            "body": f"({error.detail})",
            "missing_fields": last.get("missing_fields", []),
            "attachments": [],
        }

    def result(self):
        state = self.client.session(self.session_id)
        return state.get("result") or {"deal": False, "end_reason": state.get("end_reason"), **state}


def latest(events):
    """The supplier's latest message in a thread."""
    return next(m for m in reversed(events) if m.get("from") != "buyer")


def standing(events):
    """(term_sheet_id, terms) of the supplier's standing term sheet, or (None, {})."""
    sheets = latest(events).get("term_sheets") or []
    return (sheets[0]["term_sheet_id"], sheets[0]["terms"]) if sheets else (None, {})


def live_threads(threads):
    """Suppliers whose thread has not ended."""
    return [sid for sid, ev in threads.items() if latest(ev).get("status") not in ENDED]


def moves_left(case, events):
    """Messages you may still send in this thread (the round limit counts each of them)."""
    return case.get("round_limit", 10) - sum(m.get("from") == "buyer" for m in events)


class _NamedBytesIO(io.BytesIO):
    """Bytes stream that lets the CSV extractor retain a useful attachment source name."""

    def __init__(self, data, name):
        super().__init__(data)
        self.name = name


def _supplier_attachment_source(name):
    """Use a safe source label while keeping the supplier's original name on the attachment."""
    basename = str(name or "upload.csv").replace("\\", "/").rsplit("/", 1)[-1]
    return f"supplier_attachment_{basename}"


def _parse_csv_attachment(data, name, supplier_id=None):
    from .quote_extract import extract, extract_supplier_context

    stream = _NamedBytesIO(data, _supplier_attachment_source(name))
    if supplier_id:
        parsed = extract_supplier_context(stream, supplier_id=supplier_id)
        return parsed["records"], {"supplier_id": supplier_id, "contexts": parsed["contexts"]}
    return extract(stream), None


def fetch_documents(table, message, supplier_id=None):
    """Download supplier attachments, expose readable text, and parse CSV evidence.

    CSV attachments get ``csv_records`` plus a supplier-scoped ``supplier_context``
    when the caller supplies the thread's supplier ID; PDFs get readable text. The
    supplier agent combines these with supplier messages into one sourced context.
    CSV parse failures remain on the attachment as ``csv_parse_error``.
    """
    for att in message.get("attachments") or []:
        name = att.get("name", "")
        is_supplier_message = message.get("from") not in {"buyer", "arena"}
        attachment_type = str(att.get("type", "")).lower()
        is_csv = is_supplier_message and (
            str(name).lower().endswith(".csv") or attachment_type in {"csv", "text/csv"}
        )
        raw = None
        if att.get("attachment_id") and "text" not in att:
            raw = table.attachment(att["attachment_id"])
            att["text"] = read_document(name, raw)
        needs_context = bool(supplier_id) and not att.get("supplier_context")
        if is_csv and ("csv_records" not in att or needs_context):
            try:
                source = raw if raw is not None else att.get("text", "").encode("utf-8")
                att["csv_records"], att["supplier_context"] = _parse_csv_attachment(
                    source, name, supplier_id=supplier_id
                )
                att.pop("csv_parse_error", None)
