def test_unified_agent_uses_its_last_buyer_message_then_accepts_a_valid_supplier_final():
    case = {**CASE, "round_limit": 1, "buyer": {**CASE["buyer"], "fallback_unit_price": 42.0}}
    agent = UnifiedAgent()
    events = [supplier("open", 42.0)]

